(function(){
const key='almeida-customer-session';let session=null;
const api=(path,opt={})=>fetch(ALMEIDA_SUPABASE_URL+path,{...opt,headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+(session?.access_token||ALMEIDA_SUPABASE_KEY),'Content-Type':'application/json',...(opt.headers||{})}}).then(async r=>{const t=await r.text();let d=t?JSON.parse(t):null;if(!r.ok)throw Error(d?.message||d?.error_description||'Não foi possível concluir.');return d});
const confirmationRedirect='https://almeida-construcoes.pages.dev/';
function authError(data,status){
const code=data?.error_code||data?.code;
const messages={email_not_confirmed:'Confirme seu e-mail pelo link mais recente recebido. Se necessário, solicite um novo link.',invalid_credentials:'E-mail ou senha incorretos.',otp_expired:'Este link de confirmação expirou ou já foi utilizado. Tente entrar com sua senha ou solicite um novo link.',over_email_send_rate_limit:'O limite de envio de e-mails foi atingido. Aguarde antes de solicitar outro link.',over_request_rate_limit:'Muitas tentativas seguidas. Aguarde antes de tentar novamente.'};
return messages[code]||(status===429?'Aguarde antes de solicitar outro e-mail.':data?.error_description||data?.msg||data?.message||'Não foi possível concluir o acesso. Tente novamente.');
}
async function authRequest(path,body){
const response=await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/'+path,{method:'POST',headers:{apikey:ALMEIDA_SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify(body)});
const raw=await response.text();let data={};
try{data=raw?JSON.parse(raw):{}}catch{throw Error('O serviço de acesso retornou uma resposta inválida. Tente novamente.')}
if(!response.ok)throw Error(authError(data,response.status));return data;
}
function authSession(data){
const value=data?.session||data;
if(!value?.access_token||!value?.refresh_token)return null;
return {...value,expires_at:Number(value.expires_at)||Math.floor(Date.now()/1000)+Number(value.expires_in||3600)};
}
function saveSession(value){session=value;if(value)localStorage.setItem(key,JSON.stringify(value));else localStorage.removeItem(key)}
function showAuthNotice(message,error=false){
let notice=document.querySelector('#auth-notice');
if(!notice){notice=document.createElement('p');notice.id='auth-notice';notice.className='notice';notice.setAttribute('role','status');document.body.prepend(notice)}
notice.textContent=message;notice.classList.toggle('error',error);
}
async function load(){
try{session=JSON.parse(localStorage.getItem(key)||'null')}catch{session=null}
const hash=new URLSearchParams(location.hash.slice(1)),query=new URLSearchParams(location.search);
const callback=hash.has('access_token')||hash.has('error')||query.has('token_hash')||query.has('error');
if(!callback)return;
// Clear sensitive callback data before any asynchronous request.
for(const name of ['token_hash','type','error','error_code','error_description'])query.delete(name);
history.replaceState({},document.title,location.pathname+(query.size?'?'+query.toString():''));
try{
if(hash.has('error')||new URLSearchParams(callbackQuery).has('error'))throw Error(authError(Object.fromEntries(hash.has('error')?hash:new URLSearchParams(callbackQuery))));
let next=authSession(Object.fromEntries(hash));
const originalQuery=new URLSearchParams(callbackQuery);
if(originalQuery.has('token_hash')){
const type=originalQuery.get('type');if(!['signup','email'].includes(type))throw Error('Link de confirmação inválido. Solicite um novo link.');
next=authSession(await authRequest('verify',{token_hash:originalQuery.get('token_hash'),type}));
}
if(!next)throw Error('Não foi possível concluir a confirmação. Solicite um novo link.');
const response=await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/user',{headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+next.access_token}});
const user=await response.json();if(!response.ok)throw Error(authError(user,response.status));
if(!user.email_confirmed_at)throw Error('Seu e-mail ainda não foi confirmado. Solicite um novo link.');
next.user=user;saveSession(next);updateNav();showAuthNotice('E-mail confirmado. Sua conta está conectada.');account();
}catch(error){showAuthNotice(error.message,true)}
}
const callbackQuery=location.search;
function dialog(){if(document.querySelector('#account-dialog'))return;document.body.insertAdjacentHTML('beforeend',`<dialog id="account-dialog"><button class="close" data-close>×</button><div id="account-view"></div></dialog><dialog id="orders-dialog"><button class="close" data-close>×</button><div id="orders-view"></div></dialog>`);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close())}
function account(){dialog();const v=document.querySelector('#account-view');if(session){v.innerHTML=`<h2>Minha conta</h2><p>Você está conectado.</p><label class="field">Nome<input id="account-name" value=""></label><label class="field">Telefone<input id="account-phone"></label><label class="field">Endereço padrão<textarea id="account-address" rows="3"></textarea></label><p>Cashback: 2% sobre o valor pago após a confirmação da venda.</p><p id="account-balance"></p><button class="primary" id="save-account">Salvar dados</button> <button class="secondary" id="signout">Sair</button>`;api('/auth/v1/user').then(u=>{const p=api('/rest/v1/profiles?select=full_name,phone,default_address&id=eq.'+u.id);return Promise.all([u,p])}).then(([u,p])=>{const x=p?.[0]||{};document.querySelector('#account-name').value=x.full_name||u.user_metadata?.full_name||'';document.querySelector('#account-phone').value=x.phone||'';document.querySelector('#account-address').value=x.default_address?.text||''});api('/rest/v1/wallet_entries?select=entry_type,amount_cents').then(rows=>{const b=rows.reduce((n,x)=>n+(x.entry_type==='credit'?x.amount_cents:-x.amount_cents),0);document.querySelector('#account-balance').textContent='Cashback disponível: '+money(Math.max(0,b))}).catch(()=>{});document.querySelector('#save-account').onclick=async()=>{const u=await api('/auth/v1/user');await api('/rest/v1/profiles?id=eq.'+u.id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({full_name:document.querySelector('#account-name').value.trim(),phone:document.querySelector('#account-phone').value.trim(),default_address:{text:document.querySelector('#account-address').value.trim()}})});alert('Dados salvos.')};document.querySelector('#signout').onclick=()=>{session=null;localStorage.removeItem(key);document.querySelector('#account-dialog').close();updateNav()}}
else{v.innerHTML=`<h2>Minha conta</h2><form id="customer-login" class="admin-form"><label>E-mail<input id="customer-email" type="email" required></label><label>Senha<input id="customer-password" type="password" required minlength="6"></label><label class="show-password"><input id="show-customer-password" type="checkbox"> Mostrar senha</label><button class="primary">Entrar</button></form><button type="button" id="resend-confirmation" class="secondary signup-cta">Reenviar confirmação de e-mail</button><button type="button" id="show-signup" class="secondary signup-cta">Ainda não tenho cadastro</button><div id="signup-panel" hidden><hr><h3>Criar cadastro</h3><form id="customer-signup" class="admin-form"><label>Nome<input id="customer-name" required></label><label>Data de nascimento<input id="customer-birth-date" type="date" required></label><label>E-mail<input id="customer-signup-email" type="email" required></label><label>Telefone<input id="customer-phone" type="tel" required inputmode="tel" placeholder="(32) 99999-9999" maxlength="15"></label><label>Rua<input id="customer-street" required></label><label>Bairro<input id="customer-neighborhood" required></label><label>Número<input id="customer-number" required inputmode="numeric"></label><label>Referência<input id="customer-reference" placeholder="Opcional"></label><label>Senha<input id="customer-signup-password" type="password" required minlength="6"></label><label class="show-password"><input id="show-signup-password" type="checkbox"> Mostrar senha</label><button class="primary">Criar conta</button></form></div><p id="customer-message" class="admin-message"></p>`;document.querySelector('#customer-login').onsubmit=e=>auth(e,false);document.querySelector('#resend-confirmation').onclick=async()=>{
const email=document.querySelector('#customer-email').value.trim(),msg=document.querySelector('#customer-message'),button=document.querySelector('#resend-confirmation');
if(!email){msg.textContent='Digite seu e-mail para reenviar a confirmação.';return}
button.disabled=true;msg.classList.remove('error');msg.textContent='Solicitando novo link...';
try{await authRequest('resend?redirect_to='+encodeURIComponent(confirmationRedirect),{type:'signup',email});msg.textContent='Se o cadastro estiver aguardando confirmação, você receberá um novo link. Use apenas o e-mail mais recente. Se já confirmou, entre com sua senha.';setTimeout(()=>{button.disabled=false},60000)}catch(error){msg.textContent=error.message;msg.classList.add('error');button.disabled=false}
};document.querySelector('#customer-signup').onsubmit=e=>auth(e,true);document.querySelector('#show-signup').onclick=()=>{document.querySelector('#signup-panel').hidden=false;document.querySelector('#show-signup').hidden=true};document.querySelector('#show-customer-password').onchange=e=>document.querySelector('#customer-password').type=e.target.checked?'text':'password';document.querySelector('#show-signup-password').onchange=e=>document.querySelector('#customer-signup-password').type=e.target.checked?'text':'password';document.querySelector('#customer-phone').oninput=e=>{let n=e.target.value.replace(/\D/g,'').slice(0,11);e.target.value=n.length>10?'('+n.slice(0,2)+') '+n.slice(2,7)+'-'+n.slice(7):n.length>2?'('+n.slice(0,2)+') '+n.slice(2):n}}document.querySelector('#account-dialog').showModal()}
async function auth(e,signup){e.preventDefault();const msg=document.querySelector('#customer-message');msg.textContent='Entrando...';msg.classList.remove('error');try{const email=(signup?document.querySelector('#customer-signup-email'):document.querySelector('#customer-email')).value.trim(),password=(signup?document.querySelector('#customer-signup-password'):document.querySelector('#customer-password')).value;const d=await authRequest(signup?'signup?redirect_to='+encodeURIComponent(confirmationRedirect):'token?grant_type=password',signup?{email,password,data:{full_name:document.querySelector('#customer-name').value.trim(),phone:document.querySelector('#customer-phone')?.value.trim(),birth_date:document.querySelector('#customer-birth-date')?.value||null,default_address:{street:document.querySelector('#customer-street')?.value.trim(),neighborhood:document.querySelector('#customer-neighborhood')?.value.trim(),number:document.querySelector('#customer-number')?.value.trim(),reference:document.querySelector('#customer-reference')?.value.trim()}}}:{email,password});const next=authSession(d);if(!next){if(!signup)throw Error('O serviço não retornou uma sessão válida. Tente novamente.');msg.textContent='Confira seu e-mail para confirmar o cadastro. Use apenas o link mais recente.';return}saveSession(next);if(signup&&d.user){await api('/rest/v1/profiles?id=eq.'+d.user.id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({full_name:document.querySelector('#customer-name').value.trim(),phone:document.querySelector('#customer-phone').value.trim(),birth_date:document.querySelector('#customer-birth-date').value||null,default_address:{street:document.querySelector('#customer-street').value.trim(),neighborhood:document.querySelector('#customer-neighborhood').value.trim(),number:document.querySelector('#customer-number').value.trim(),reference:document.querySelector('#customer-reference').value.trim()}})})}document.querySelector('#account-dialog').close();updateNav()}catch(x){msg.textContent=x.message;msg.classList.add('error')}}
function updateNav(){const a=document.querySelector('#account');if(a)a.textContent=session?'Minha conta ✓':'Minha conta'}
async function orders(){dialog();const v=document.querySelector('#orders-view');if(!session){v.innerHTML='<h2>Meus pedidos</h2><p>Entre na sua conta para visualizar seus pedidos.</p>';document.querySelector('#orders-dialog').showModal();return}try{const rows=await api('/rest/v1/orders?select=id,public_number,status,payment_method,amount_due_cents,cashback_reserved_cents,cashback_credited_cents,created_at,order_items(product_name,variant_name,quantity,line_total_cents)&order=created_at.desc');v.innerHTML='<h2>Meus pedidos</h2>'+(rows.length?rows.map(o=>`<article class="order-card"><strong>Pedido #${o.public_number}</strong><span>${o.status==='pending'?'Aguardando confirmação':o.status==='confirmed'?'Confirmado':'Cancelado'}</span><p>${o.order_items.map(i=>`${i.quantity}× ${i.product_name} — ${money(i.line_total_cents)}`).join('<br>')}</p><b>Total: ${money(o.amount_due_cents)}</b></article>`).join(''):'<p>Você ainda não tem pedidos.</p>')}catch(e){v.innerHTML='<p>'+e.message+'</p>'}document.querySelector('#orders-dialog').showModal()}
async function sendOrder(){if(!session){account();return}const payment=$('#payment').value==='cartao'?'card':$('#payment').value==='dinheiro'?'cash':'pix',fulfillment=$('#fulfillment').value==='entrega'?'delivery':'pickup',addr=$('#address')?.value.trim(),requested=Math.max(0,Math.round(Number($('#cashback-use')?.value||0)*100));if(fulfillment==='delivery'&&!addr){$('#address').focus();return}const items=cart.map(i=>({variant_id:produtos[i.id].variacoes[i.vi].id,quantity:i.qty}));if(items.some(i=>!i.variant_id)){alert('Atualize o catálogo antes de finalizar o pedido.');return}const result=await api('/rest/v1/rpc/place_order',{method:'POST',body:JSON.stringify({p_items:items,p_payment_method:payment,p_fulfillment_method:fulfillment,p_delivery_address:addr?{text:addr}:null,p_cashback_requested_cents:requested})});const lines=cart.map(i=>{const p=produtos[i.id],v=p.variacoes[i.vi];return `${i.qty}× ${p.nome} — ${v.nome}`});const msg=`Olá! Pedido #${result.public_number} da Almeida Construções.\n\n${lines.join('\n')}\n\nTotal: ${money(result.amount_due_cents)}\nPagamento: ${payment==='pix'?'PIX':payment==='cash'?'Dinheiro':'Cartão'}\nPedido registrado no site e aguardando confirmação.`;window.open('https://wa.me/553220201300?text='+encodeURIComponent(msg),'_blank','noopener');cart=[];saveCart();$('#cart-dialog').close();alert('Pedido registrado! Você pode acompanhar em Meus pedidos.');}
const authReady=load();if(document.querySelector('#account')){dialog();document.querySelector('#account').onclick=async()=>{await authReady;account()};if(document.querySelector('#orders'))document.querySelector('#orders').onclick=async()=>{await authReady;orders()};updateNav();}if(typeof send==='function')send=()=>sendOrder();
})();
